@sig trait Availability_Assessment_Api {
  def id: Art.BridgeId
  def raw_availability_Id : Art.PortId
  def availability_assessment_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var availability_assessment: Factory_Dispatch_Coordinator.Availability_Assessment_Value.Type = $

  def put_availability_assessment(value : Factory_Dispatch_Coordinator.Availability_Assessment_Value.Type) : Unit = {
    Contract(
      Modifies(availability_assessment),
      Ensures(
        availability_assessment == value
      )
    )
    Spec {
      availability_assessment = value
    }

    Art.putValue(availability_assessment_Id, Factory_Dispatch_Coordinator.Availability_Assessment_Value_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Availability_Assessment_Initialization_Api (
  val id: Art.BridgeId,
  val raw_availability_Id : Art.PortId,
  val availability_assessment_Id : Art.PortId) extends Availability_Assessment_Api

@datatype class Availability_Assessment_Operational_Api (
  val id: Art.BridgeId,
  val raw_availability_Id : Art.PortId,
  val availability_assessment_Id : Art.PortId) extends Availability_Assessment_Api {

  // Logika spec var representing port state for incoming data port
  @spec var raw_availability: Factory_Dispatch_Coordinator.Product_Availability_Sample = $

  def get_raw_availability() : Option[Factory_Dispatch_Coordinator.Product_Availability_Sample] = {
    Contract(
      Ensures(
        Res == Some(raw_availability)
      )
    )
    val value : Option[Factory_Dispatch_Coordinator.Product_Availability_Sample] = Art.getValue(raw_availability_Id) match {
      case Some(Factory_Dispatch_Coordinator.Product_Availability_Sample_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port raw_availability.  Expecting 'Factory_Dispatch_Coordinator.Product_Availability_Sample_Payload' but received ${v}")
        None[Factory_Dispatch_Coordinator.Product_Availability_Sample]()
      case _ => None[Factory_Dispatch_Coordinator.Product_Availability_Sample]()
    }
    return value
  }
}
